from store import vector_store


def recall_at_k(labelled_cases, k=10):
    """retrieval_recall computed per index build, independent of the answer score."""
    hits = 0
    for case in labelled_cases:
        got = [c.id for c in vector_store.similarity_search(case["question"], top_k=k)]
        hits += int(any(doc_id in got for doc_id in case["relevant_doc_ids"]))
    return hits / len(labelled_cases)
